    private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
        if (prefix == null || str == null) {
            return prefix == null && str == null;
        }
        if (ignoreCase) {
            return str.substring(0, prefix.length()).equalsIgnoreCase(prefix);
        } else {
            return str.startsWith(prefix);
        }
    }

    public static void main(String[] args) {
        System.out.println(startsWith("hello", "HE", true)); // true
        System.out.println(startsWith("hello", "he", true)); // true
        System.out.println(startsWith("hello", "he", false)); // true
        System.out.println(startsWith("hello", "lo", true)); // false
        System.out.println(startsWith(null, null, true)); // true
        System.out.println(startsWith(null, "he", true)); // false
        System.out.println(startsWith("hello", null, true)); // false
    }
}

