import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[1024]; // Initial capacity
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            Arrays.fill(data, length, length + byteLength, (byte) 0);
        } else {
            if (length + byteLength > data.length) {
                enlarge(byteLength);
            }
            System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
        }
        length += byteLength;
        return this;
    }

    private void enlarge(int additionalCapacity) {
        int newCapacity = Math.max(data.length * 2, length + additionalCapacity);
        data = Arrays.copyOf(data, newCapacity);
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byteVector.putByteArray(new byte[]{1, 2, 3, 4}, 0, 4);
        System.out.println(Arrays.toString(byteVector.data));
    }
}

