            int argCount = 0;
            for (char ch : argTypes.toCharArray()) {
                if (ch != ')') {
                    argCount++;
                }
            }
            for (int i = 0; i < argCount; i++) {
                stack.pop();
            }
        } else {
            // Single type descriptor
            stack.pop();
        }
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        frameStack.stack.push(1); // int
        frameStack.stack.push(2.0); // double
        frameStack.stack.push("hello"); // String
        frameStack.stack.push(true); // boolean

        frameStack.pop("(IDLjava/lang/String;Z)V"); // (I DLjava/lang/String; Z)V
        System.out.println(frameStack.stack.size()); // Output: 1

        frameStack.pop("Ljava/lang/String;"); // Ljava/lang/String;
        System.out.println(frameStack.stack.size()); // Output: 0
    }
}

