public class TimeRangeBuilder {

    private static final long FETCH_DATA_DURATION = 3600000; // 1 hour in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long duration = end - start;

        if (duration <= FETCH_DATA_DURATION) {
            timeRanges.add(new TimeRange(start, end));
        } else {
            while (start < end) {
                long nextEnd = Math.min(start + FETCH_DATA_DURATION, end);
                timeRanges.add(new TimeRange(start, nextEnd));
                start = nextEnd;
            }
        }

        return timeRanges;
    }

    public static void main(String[] args) {
        TimeRangeBuilder builder = new TimeRangeBuilder();
        List<TimeRange> ranges = builder.buildTimeRanges(1633072800000L, 1633159200000L);

        for (TimeRange range : ranges) {
            System.out.println("Start: " + range.getStart() + ", End: " + range.getEnd());
        }
    }
}

